  es: {"probe.sidebar": "Buscar passkeys y leer contenido", "probe.title": "Encontrar passkeys preguntando", "probe.intro": "Esta llave (FIDO 2.0) no puede listar sus passkeys. KeyMelier puede preguntarle sitio por sitio: tus sitios conocidos, servicios de passkeys habituales y tus propios dominios.", "probe.start": "Buscar passkeys", "probe.again": "Buscar de nuevo", "probe.dialogTitle": "Buscar passkeys en {name}", "probe.dialogText": "KeyMelier pregunta a la llave en silencio (sin tocar), sitio por sitio, si tiene cuentas allí. Con el PIN también da los nombres de las cuentas (UPN).", "probe.pin": "PIN – necesario para los nombres de cuenta (UPN)", "probe.extra": "Dominios propios (opcional)", "probe.progress": "{done} de {total} sitios comprobados…", "probe.note": "Solo se encuentran sitios de la lista. Cada acierto aumenta en uno el contador de uso de la passkey, algo inofensivo para los sitios.", "probe.found": "{n} cuentas en {sites} sitios", "probe.accounts": "{n} cuentas", "probe.unnamed": "Cuenta sin nombre (introduce el PIN para ver nombres)", "probe.checked": "Encontrado preguntando · {n} sitios comprobados · {when}"},
