const RP_STRINGS = {
  de: {"rp.title": "Alten Schlüssel ersetzen", "rp.text": "Vergleicht, was KeyMelier über den alten Schlüssel weiß, mit dem neuen – und begleitet dich Dienst für Dienst beim Umzug.", "rp.old": "Alter Schlüssel", "rp.new": "Neuer Schlüssel", "rp.choose": "Schlüssel wählen …", "rp.check.found": "auf dem neuen Key gefunden", "rp.check.similar": "ähnlicher Eintrag – nicht eindeutig", "rp.check.missing": "auf dem neuen Key nicht gefunden", "rp.check.unknown": "neuer Key noch nicht gelesen", "rp.confirmed": "von dir bestätigt", "rp.sum.total": "Einträge auf dem alten Key", "rp.sum.found": "technisch auf dem neuen Key gefunden", "rp.sum.confirmed": "von dir als erledigt bestätigt", "rp.legend": "„Gefunden“ prüft KeyMelier selbst anhand dessen, was der neue Key beim letzten Auslesen gezeigt hat. Das Häkchen ist nur deine Bestätigung – KeyMelier kann nicht prüfen, ob die Anmeldung beim Dienst funktioniert.", "rp.empty": "Über den alten Schlüssel ist noch nichts bekannt. Stecke ihn an und lies Passkeys, Codes, OpenPGP und PIV einmal aus.", "rp.noRemember": "„Inhalte merken“ ist aus – ohne gespeicherte Inhalte kann KeyMelier die Schlüssel nicht vergleichen und keinen Fortschritt festhalten.", "rp.readNew": "Der neue Key wurde noch nicht (vollständig) ausgelesen. Stecke ihn an und öffne Passkeys (mit PIN) und die übrigen Bereiche – dann prüft KeyMelier die Einträge.", "rp.session": "Der Verlauf ist aus: Der Fortschritt gilt nur bis zum Beenden von KeyMelier.", "rp.pk.title": "Passkeys", "rp.pk.hint": "Passkeys lassen sich nicht kopieren – der private Schlüssel verlässt den Key nie. Melde dich beim Dienst an, füge dort den neuen Key als weiteren Passkey bzw. Sicherheitsschlüssel hinzu und teste die Anmeldung damit. Entferne den alten Key beim Dienst erst danach.", "rp.oath.hint": "Das Geheimnis eines Codes lässt sich nicht vom Key auslesen. Richte die Zwei-Faktor-Anmeldung beim Dienst neu ein (neuer QR-Code) – oder füge den ursprünglichen QR-Code hinzu, falls du ihn sicher aufbewahrt hast.", "rp.pgp.hint": "Nur mit einer Sicherung des privaten Schlüssels (in gpg erzeugt und dann auf den Key übertragen) kannst du dieselben Schlüssel auf den neuen Key laden – der Fingerabdruck stimmt dann überein. Auf dem Key erzeugte Schlüssel lassen sich nicht übertragen: neue erzeugen, den öffentlichen Schlüssel verteilen und den alten widerrufen.", "rp.piv.hint": "PIV-Schlüssel, die auf dem Key erzeugt wurden, lassen sich nicht übertragen. Erzeuge auf dem neuen Key ein neues Schlüsselpaar und lass das Zertifikat bei der ausstellenden Stelle (z. B. deiner IT) neu ausstellen. Ein Zertifikat mit gleichem Namen ist nur ein Hinweis, nicht derselbe Schlüssel.", "rp.otp.hint": "Den Inhalt eines OTP-Slots kann niemand auslesen. Richte statisches Passwort oder Challenge-Response auf dem neuen Key neu ein (mit deinem gesicherten Geheimnis) und hinterlege ihn beim Dienst bzw. Programm.", "rp.never": "KeyMelier setzt keinen der beiden Keys zurück und löscht nichts. Wenn alles umgezogen ist und du dich überall mit dem neuen Key anmelden kannst, entferne den alten Key bei jedem Dienst – erst dann kannst du ihn selbst zurücksetzen.", "rp.openNew": "Neuen Key öffnen", "rp.openNewOffline": "Neuen Key anzeigen (nicht angesteckt)", "rp.stop": "Vergleich beenden"},
  en: {"rp.title": "Replace an old key", "rp.text": "Compares what KeyMelier knows about the old key with the new one – and walks you through moving each service.", "rp.old": "Old key", "rp.new": "New key", "rp.choose": "Choose a key…", "rp.check.found": "found on the new key", "rp.check.similar": "similar entry – not conclusive", "rp.check.missing": "not found on the new key", "rp.check.unknown": "new key not read yet", "rp.confirmed": "confirmed by you", "rp.sum.total": "entries on the old key", "rp.sum.found": "technically found on the new key", "rp.sum.confirmed": "confirmed as done by you", "rp.legend": "“Found” is checked by KeyMelier itself, from what the new key showed when it was last read. The tick is only your confirmation – KeyMelier cannot check whether signing in at the service works.", "rp.empty": "Nothing is known about the old key yet. Plug it in and read its passkeys, codes, OpenPGP and PIV once.", "rp.noRemember": "“Remember contents” is off – without stored contents KeyMelier cannot compare the keys or keep progress.", "rp.readNew": "The new key has not been read (completely) yet. Plug it in and open Passkeys (with the PIN) and the other areas – then KeyMelier checks the entries.", "rp.session": "History is off: progress is only kept until KeyMelier quits.", "rp.pk.title": "Passkeys", "rp.pk.hint": "Passkeys cannot be copied – the private key never leaves the key. Sign in at the service, add the new key there as another passkey or security key, and test signing in with it. Only then remove the old key at the service.", "rp.oath.hint": "A code's secret cannot be read from the key. Set up two-factor sign-in at the service again (new QR code) – or add the original QR code if you kept it safe.", "rp.pgp.hint": "Only with a backup of the private key (created in gpg and then moved to the key) can you load the same keys onto the new key – the fingerprint then matches. Keys generated on the key cannot be transferred: generate new ones, publish the public key and revoke the old one.", "rp.piv.hint": "PIV keys generated on the key cannot be transferred. Generate a new key pair on the new key and have the certificate reissued by whoever issued it (e.g. your IT). A certificate with the same name is only a hint, not the same key.", "rp.otp.hint": "Nobody can read an OTP slot. Program the static password or challenge-response again on the new key (using your saved secret) and register it with the service or program.", "rp.never": "KeyMelier resets neither key and deletes nothing. Once everything has moved and you can sign in everywhere with the new key, remove the old key at every service – only then reset it yourself.", "rp.openNew": "Open new key", "rp.openNewOffline": "Show new key (not plugged in)", "rp.stop": "Stop comparing"},
  es: {"rp.title": "Sustituir una llave antigua", "rp.text": "Compara lo que KeyMelier sabe de la llave antigua con la nueva y te guía servicio por servicio en el cambio.", "rp.old": "Llave antigua", "rp.new": "Llave nueva", "rp.choose": "Elige una llave…", "rp.check.found": "encontrado en la llave nueva", "rp.check.similar": "entrada similar – no concluyente", "rp.check.missing": "no encontrado en la llave nueva", "rp.check.unknown": "llave nueva aún no leída", "rp.confirmed": "confirmado por ti", "rp.sum.total": "entradas en la llave antigua", "rp.sum.found": "encontradas técnicamente en la llave nueva", "rp.sum.confirmed": "confirmadas por ti como hechas", "rp.legend": "«Encontrado» lo comprueba KeyMelier según lo que mostró la llave nueva la última vez que se leyó. La marca es solo tu confirmación: KeyMelier no puede comprobar si el inicio de sesión en el servicio funciona.", "rp.empty": "Aún no se sabe nada de la llave antigua. Conéctala y lee una vez sus passkeys, códigos, OpenPGP y PIV.", "rp.noRemember": "«Recordar contenido» está desactivado: sin contenido guardado KeyMelier no puede comparar las llaves ni guardar el progreso.", "rp.readNew": "La llave nueva aún no se ha leído (por completo). Conéctala y abre Passkeys (con el PIN) y las demás secciones; así KeyMelier comprueba las entradas.", "rp.session": "El historial está desactivado: el progreso solo se conserva hasta cerrar KeyMelier.", "rp.pk.title": "Passkeys", "rp.pk.hint": "Las passkeys no se pueden copiar: la clave privada nunca sale de la llave. Inicia sesión en el servicio, añade allí la llave nueva como otra passkey o llave de seguridad y prueba a iniciar sesión con ella. Solo después quita la llave antigua en el servicio.", "rp.oath.hint": "El secreto de un código no se puede leer de la llave. Vuelve a configurar la verificación en dos pasos en el servicio (nuevo código QR) o añade el código QR original si lo guardaste a salvo.", "rp.pgp.hint": "Solo con una copia de la clave privada (creada en gpg y luego pasada a la llave) puedes cargar las mismas claves en la llave nueva; entonces coincide la huella. Las claves generadas en la llave no se pueden transferir: genera nuevas, publica la clave pública y revoca la antigua.", "rp.piv.hint": "Las claves PIV generadas en la llave no se pueden transferir. Genera un nuevo par de claves en la llave nueva y pide que vuelvan a emitir el certificado (p. ej. tu departamento de TI). Un certificado con el mismo nombre es solo un indicio, no la misma clave.", "rp.otp.hint": "Nadie puede leer una ranura OTP. Vuelve a configurar la contraseña estática o el desafío-respuesta en la llave nueva (con tu secreto guardado) y regístrala en el servicio o programa.", "rp.never": "KeyMelier no restablece ninguna de las dos llaves ni borra nada. Cuando todo esté trasladado y puedas iniciar sesión en todas partes con la llave nueva, quita la antigua en cada servicio; solo entonces restablécela tú.", "rp.openNew": "Abrir llave nueva", "rp.openNewOffline": "Ver llave nueva (no conectada)", "rp.stop": "Terminar comparación"},
  fr: {"rp.title": "Remplacer une ancienne clé", "rp.text": "Compare ce que KeyMelier sait de l'ancienne clé avec la nouvelle – et vous accompagne service par service pendant le changement.", "rp.old": "Ancienne clé", "rp.new": "Nouvelle clé", "rp.choose": "Choisir une clé…", "rp.check.found": "trouvé sur la nouvelle clé", "rp.check.similar": "entrée similaire – non concluant", "rp.check.missing": "absent de la nouvelle clé", "rp.check.unknown": "nouvelle clé pas encore lue", "rp.confirmed": "confirmé par vous", "rp.sum.total": "entrées sur l'ancienne clé", "rp.sum.found": "trouvées techniquement sur la nouvelle clé", "rp.sum.confirmed": "confirmées comme faites par vous", "rp.legend": "« Trouvé » est vérifié par KeyMelier d'après ce que la nouvelle clé a montré lors de sa dernière lecture. La coche n'est que votre confirmation – KeyMelier ne peut pas vérifier que la connexion au service fonctionne.", "rp.empty": "On ne sait encore rien de l'ancienne clé. Branchez-la et lisez une fois ses passkeys, codes, OpenPGP et PIV.", "rp.noRemember": "« Mémoriser le contenu » est désactivé – sans contenu enregistré, KeyMelier ne peut ni comparer les clés ni garder la progression.", "rp.readNew": "La nouvelle clé n'a pas encore été lue (entièrement). Branchez-la et ouvrez Passkeys (avec le PIN) et les autres sections – KeyMelier vérifiera alors les entrées.", "rp.session": "L'historique est désactivé : la progression n'est conservée que jusqu'à la fermeture de KeyMelier.", "rp.pk.title": "Passkeys", "rp.pk.hint": "Les passkeys ne peuvent pas être copiées – la clé privée ne quitte jamais la clé. Connectez-vous au service, ajoutez-y la nouvelle clé comme passkey ou clé de sécurité supplémentaire et testez la connexion avec elle. Ensuite seulement, retirez l'ancienne clé du service.", "rp.oath.hint": "Le secret d'un code ne peut pas être lu depuis la clé. Reconfigurez la double authentification sur le service (nouveau QR code) – ou ajoutez le QR code d'origine si vous l'avez conservé en lieu sûr.", "rp.pgp.hint": "Ce n'est qu'avec une sauvegarde de la clé privée (créée dans gpg puis transférée sur la clé) que vous pouvez charger les mêmes clés sur la nouvelle – l'empreinte correspond alors. Les clés générées sur la clé ne sont pas transférables : générez-en de nouvelles, publiez la clé publique et révoquez l'ancienne.", "rp.piv.hint": "Les clés PIV générées sur la clé ne sont pas transférables. Générez une nouvelle paire de clés sur la nouvelle clé et faites réémettre le certificat par l'émetteur (p. ex. votre service informatique). Un certificat au même nom n'est qu'un indice, pas la même clé.", "rp.otp.hint": "Personne ne peut lire un emplacement OTP. Reconfigurez le mot de passe statique ou le défi-réponse sur la nouvelle clé (avec votre secret sauvegardé) et enregistrez-la auprès du service ou du programme.", "rp.never": "KeyMelier ne réinitialise aucune des deux clés et ne supprime rien. Quand tout est transféré et que vous pouvez vous connecter partout avec la nouvelle clé, retirez l'ancienne de chaque service – ensuite seulement, réinitialisez-la vous-même.", "rp.openNew": "Ouvrir la nouvelle clé", "rp.openNewOffline": "Afficher la nouvelle clé (non branchée)", "rp.stop": "Arrêter la comparaison"},
  it: {"rp.title": "Sostituire una chiave vecchia", "rp.text": "Confronta ciò che KeyMelier sa della chiave vecchia con quella nuova e ti accompagna servizio per servizio nel passaggio.", "rp.old": "Chiave vecchia", "rp.new": "Chiave nuova", "rp.choose": "Scegli una chiave…", "rp.check.found": "trovato sulla chiave nuova", "rp.check.similar": "voce simile – non conclusivo", "rp.check.missing": "non trovato sulla chiave nuova", "rp.check.unknown": "chiave nuova non ancora letta", "rp.confirmed": "confermato da te", "rp.sum.total": "voci sulla chiave vecchia", "rp.sum.found": "trovate tecnicamente sulla chiave nuova", "rp.sum.confirmed": "confermate da te come fatte", "rp.legend": "«Trovato» lo verifica KeyMelier in base a ciò che la chiave nuova ha mostrato all'ultima lettura. La spunta è solo la tua conferma: KeyMelier non può verificare se l'accesso al servizio funziona.", "rp.empty": "Della chiave vecchia non si sa ancora nulla. Collegala e leggi una volta passkey, codici, OpenPGP e PIV.", "rp.noRemember": "«Ricorda contenuti» è disattivato: senza contenuti salvati KeyMelier non può confrontare le chiavi né salvare i progressi.", "rp.readNew": "La chiave nuova non è ancora stata letta (completamente). Collegala e apri Passkey (con il PIN) e le altre sezioni: così KeyMelier verifica le voci.", "rp.session": "La cronologia è disattivata: i progressi valgono solo fino alla chiusura di KeyMelier.", "rp.pk.title": "Passkey", "rp.pk.hint": "Le passkey non si possono copiare: la chiave privata non lascia mai la chiave. Accedi al servizio, aggiungi lì la chiave nuova come ulteriore passkey o chiave di sicurezza e prova ad accedere con essa. Solo dopo rimuovi la chiave vecchia dal servizio.", "rp.oath.hint": "Il segreto di un codice non si può leggere dalla chiave. Riconfigura la verifica in due passaggi sul servizio (nuovo codice QR) oppure aggiungi il codice QR originale se l'hai conservato al sicuro.", "rp.pgp.hint": "Solo con un backup della chiave privata (creata in gpg e poi trasferita sulla chiave) puoi caricare le stesse chiavi sulla nuova: l'impronta allora coincide. Le chiavi generate sulla chiave non si possono trasferire: generane di nuove, pubblica la chiave pubblica e revoca quella vecchia.", "rp.piv.hint": "Le chiavi PIV generate sulla chiave non si possono trasferire. Genera una nuova coppia di chiavi sulla chiave nuova e fai riemettere il certificato da chi lo ha emesso (ad es. il tuo reparto IT). Un certificato con lo stesso nome è solo un indizio, non la stessa chiave.", "rp.otp.hint": "Nessuno può leggere uno slot OTP. Riconfigura la password statica o il challenge-response sulla chiave nuova (con il tuo segreto salvato) e registrala presso il servizio o il programma.", "rp.never": "KeyMelier non ripristina nessuna delle due chiavi e non cancella nulla. Quando tutto è stato trasferito e puoi accedere ovunque con la chiave nuova, rimuovi la vecchia da ogni servizio: solo allora ripristinala tu.", "rp.openNew": "Apri chiave nuova", "rp.openNewOffline": "Mostra chiave nuova (non collegata)", "rp.stop": "Termina confronto"},
  nl: {"rp.title": "Oude sleutel vervangen", "rp.text": "Vergelijkt wat KeyMelier over de oude sleutel weet met de nieuwe – en begeleidt je dienst voor dienst bij het overzetten.", "rp.old": "Oude sleutel", "rp.new": "Nieuwe sleutel", "rp.choose": "Kies een sleutel…", "rp.check.found": "gevonden op de nieuwe sleutel", "rp.check.similar": "vergelijkbaar item – niet eenduidig", "rp.check.missing": "niet gevonden op de nieuwe sleutel", "rp.check.unknown": "nieuwe sleutel nog niet gelezen", "rp.confirmed": "door jou bevestigd", "rp.sum.total": "items op de oude sleutel", "rp.sum.found": "technisch gevonden op de nieuwe sleutel", "rp.sum.confirmed": "door jou als gedaan bevestigd", "rp.legend": "‘Gevonden’ controleert KeyMelier zelf, op basis van wat de nieuwe sleutel bij het laatste uitlezen liet zien. Het vinkje is alleen jouw bevestiging – KeyMelier kan niet controleren of inloggen bij de dienst werkt.", "rp.empty": "Over de oude sleutel is nog niets bekend. Sluit hem aan en lees passkeys, codes, OpenPGP en PIV één keer uit.", "rp.noRemember": "‘Inhoud onthouden’ staat uit – zonder opgeslagen inhoud kan KeyMelier de sleutels niet vergelijken en geen voortgang bewaren.", "rp.readNew": "De nieuwe sleutel is nog niet (volledig) uitgelezen. Sluit hem aan en open Passkeys (met pincode) en de andere onderdelen – dan controleert KeyMelier de items.", "rp.session": "De geschiedenis staat uit: de voortgang geldt alleen tot KeyMelier wordt afgesloten.", "rp.pk.title": "Passkeys", "rp.pk.hint": "Passkeys kun je niet kopiëren – de privésleutel verlaat de sleutel nooit. Log in bij de dienst, voeg daar de nieuwe sleutel toe als extra passkey of beveiligingssleutel en test het inloggen ermee. Verwijder pas daarna de oude sleutel bij de dienst.", "rp.oath.hint": "Het geheim van een code kan niet van de sleutel worden gelezen. Stel tweestapsverificatie bij de dienst opnieuw in (nieuwe QR-code) – of voeg de oorspronkelijke QR-code toe als je die veilig hebt bewaard.", "rp.pgp.hint": "Alleen met een back-up van de privésleutel (in gpg gemaakt en daarna naar de sleutel gezet) kun je dezelfde sleutels op de nieuwe sleutel laden – de vingerafdruk komt dan overeen. Op de sleutel gegenereerde sleutels zijn niet over te zetten: maak nieuwe, publiceer de publieke sleutel en trek de oude in.", "rp.piv.hint": "PIV-sleutels die op de sleutel zijn gegenereerd, zijn niet over te zetten. Genereer een nieuw sleutelpaar op de nieuwe sleutel en laat het certificaat opnieuw uitgeven door de uitgever (bijv. je IT-afdeling). Een certificaat met dezelfde naam is alleen een aanwijzing, niet dezelfde sleutel.", "rp.otp.hint": "Niemand kan een OTP-slot uitlezen. Stel het statische wachtwoord of challenge-response opnieuw in op de nieuwe sleutel (met je bewaarde geheim) en registreer hem bij de dienst of het programma.", "rp.never": "KeyMelier zet geen van beide sleutels terug en verwijdert niets. Als alles is overgezet en je overal met de nieuwe sleutel kunt inloggen, verwijder dan de oude bij elke dienst – pas daarna zet je hem zelf terug.", "rp.openNew": "Nieuwe sleutel openen", "rp.openNewOffline": "Nieuwe sleutel tonen (niet aangesloten)", "rp.stop": "Vergelijking beëindigen"},
  pl: {"rp.title": "Zastąp stary klucz", "rp.text": "Porównuje to, co KeyMelier wie o starym kluczu, z nowym – i prowadzi cię usługa po usłudze przez przeniesienie.", "rp.old": "Stary klucz", "rp.new": "Nowy klucz", "rp.choose": "Wybierz klucz…", "rp.check.found": "znaleziono na nowym kluczu", "rp.check.similar": "podobny wpis – niejednoznaczne", "rp.check.missing": "nie znaleziono na nowym kluczu", "rp.check.unknown": "nowy klucz jeszcze nieodczytany", "rp.confirmed": "potwierdzone przez ciebie", "rp.sum.total": "wpisy na starym kluczu", "rp.sum.found": "technicznie znalezione na nowym kluczu", "rp.sum.confirmed": "potwierdzone przez ciebie jako zrobione", "rp.legend": "„Znaleziono” sprawdza sam KeyMelier na podstawie tego, co nowy klucz pokazał przy ostatnim odczycie. Znacznik to tylko twoje potwierdzenie – KeyMelier nie może sprawdzić, czy logowanie w usłudze działa.", "rp.empty": "O starym kluczu nic jeszcze nie wiadomo. Podłącz go i raz odczytaj passkeys, kody, OpenPGP i PIV.", "rp.noRemember": "„Zapamiętuj zawartość” jest wyłączone – bez zapisanej zawartości KeyMelier nie może porównać kluczy ani zapisać postępu.", "rp.readNew": "Nowy klucz nie został jeszcze (w pełni) odczytany. Podłącz go i otwórz Passkeys (z PIN-em) oraz pozostałe sekcje – wtedy KeyMelier sprawdzi wpisy.", "rp.session": "Historia jest wyłączona: postęp obowiązuje tylko do zamknięcia KeyMelier.", "rp.pk.title": "Passkeys", "rp.pk.hint": "Passkeys nie da się skopiować – klucz prywatny nigdy nie opuszcza klucza. Zaloguj się w usłudze, dodaj tam nowy klucz jako kolejny passkey lub klucz bezpieczeństwa i sprawdź logowanie nim. Dopiero potem usuń stary klucz w usłudze.", "rp.oath.hint": "Sekretu kodu nie da się odczytać z klucza. Skonfiguruj ponownie weryfikację dwuetapową w usłudze (nowy kod QR) – albo dodaj oryginalny kod QR, jeśli go bezpiecznie przechowujesz.", "rp.pgp.hint": "Tylko mając kopię klucza prywatnego (utworzonego w gpg i przeniesionego na klucz) możesz wgrać te same klucze na nowy klucz – odcisk wtedy się zgadza. Kluczy wygenerowanych na kluczu nie da się przenieść: wygeneruj nowe, opublikuj klucz publiczny i unieważnij stary.", "rp.piv.hint": "Kluczy PIV wygenerowanych na kluczu nie da się przenieść. Wygeneruj nową parę kluczy na nowym kluczu i poproś wystawcę (np. dział IT) o ponowne wystawienie certyfikatu. Certyfikat o tej samej nazwie to tylko wskazówka, nie ten sam klucz.", "rp.otp.hint": "Nikt nie może odczytać slotu OTP. Skonfiguruj ponownie hasło statyczne lub challenge-response na nowym kluczu (z zapisanym sekretem) i zarejestruj go w usłudze lub programie.", "rp.never": "KeyMelier nie resetuje żadnego z kluczy i niczego nie usuwa. Gdy wszystko zostanie przeniesione i wszędzie zalogujesz się nowym kluczem, usuń stary w każdej usłudze – dopiero wtedy zresetuj go sam.", "rp.openNew": "Otwórz nowy klucz", "rp.openNewOffline": "Pokaż nowy klucz (niepodłączony)", "rp.stop": "Zakończ porównanie"},
  pt: {"rp.title": "Substituir uma chave antiga", "rp.text": "Compara o que o KeyMelier sabe da chave antiga com a nova e acompanha-te serviço a serviço na mudança.", "rp.old": "Chave antiga", "rp.new": "Chave nova", "rp.choose": "Escolher uma chave…", "rp.check.found": "encontrado na chave nova", "rp.check.similar": "entrada semelhante – inconclusivo", "rp.check.missing": "não encontrado na chave nova", "rp.check.unknown": "chave nova ainda não lida", "rp.confirmed": "confirmado por ti", "rp.sum.total": "entradas na chave antiga", "rp.sum.found": "encontradas tecnicamente na chave nova", "rp.sum.confirmed": "confirmadas por ti como feitas", "rp.legend": "«Encontrado» é verificado pelo próprio KeyMelier com base no que a chave nova mostrou na última leitura. O visto é apenas a tua confirmação – o KeyMelier não consegue verificar se o início de sessão no serviço funciona.", "rp.empty": "Ainda não se sabe nada da chave antiga. Liga-a e lê uma vez as passkeys, códigos, OpenPGP e PIV.", "rp.noRemember": "«Lembrar conteúdo» está desativado – sem conteúdo guardado o KeyMelier não consegue comparar as chaves nem guardar o progresso.", "rp.readNew": "A chave nova ainda não foi lida (completamente). Liga-a e abre Passkeys (com o PIN) e as outras secções – assim o KeyMelier verifica as entradas.", "rp.session": "O histórico está desativado: o progresso só se mantém até fechares o KeyMelier.", "rp.pk.title": "Passkeys", "rp.pk.hint": "As passkeys não podem ser copiadas – a chave privada nunca sai da chave. Inicia sessão no serviço, adiciona lá a chave nova como outra passkey ou chave de segurança e testa o início de sessão com ela. Só depois remove a chave antiga do serviço.", "rp.oath.hint": "O segredo de um código não pode ser lido da chave. Volta a configurar a verificação em dois passos no serviço (novo código QR) – ou adiciona o código QR original se o guardaste em segurança.", "rp.pgp.hint": "Só com uma cópia da chave privada (criada no gpg e depois passada para a chave) podes carregar as mesmas chaves na chave nova – a impressão digital coincide então. Chaves geradas na chave não podem ser transferidas: gera novas, publica a chave pública e revoga a antiga.", "rp.piv.hint": "Chaves PIV geradas na chave não podem ser transferidas. Gera um novo par de chaves na chave nova e pede a quem emitiu o certificado (p. ex. o teu departamento de TI) que o volte a emitir. Um certificado com o mesmo nome é só um indício, não a mesma chave.", "rp.otp.hint": "Ninguém consegue ler uma ranhura OTP. Volta a configurar a palavra-passe estática ou o desafio-resposta na chave nova (com o teu segredo guardado) e regista-a no serviço ou programa.", "rp.never": "O KeyMelier não repõe nenhuma das chaves nem apaga nada. Quando tudo estiver mudado e conseguires iniciar sessão em todo o lado com a chave nova, remove a antiga de cada serviço – só então a repões tu.", "rp.openNew": "Abrir chave nova", "rp.openNewOffline": "Mostrar chave nova (não ligada)", "rp.stop": "Terminar comparação"},
  ja: {"rp.title": "古いキーを置き換える", "rp.text": "古いキーについて KeyMelier が把握している内容を新しいキーと比較し、サービスごとの移行を案内します。", "rp.old": "古いキー", "rp.new": "新しいキー", "rp.choose": "キーを選択…", "rp.check.found": "新しいキーで確認済み", "rp.check.similar": "類似した項目 – 確定できません", "rp.check.missing": "新しいキーに見つかりません", "rp.check.unknown": "新しいキーはまだ読み取られていません", "rp.confirmed": "あなたが確認済み", "rp.sum.total": "古いキーの項目", "rp.sum.found": "新しいキーで技術的に確認", "rp.sum.confirmed": "あなたが完了と確認", "rp.legend": "「確認済み」は、新しいキーを最後に読み取ったときの内容から KeyMelier 自身が判定します。チェックはあなたの確認にすぎず、サービスへのサインインが機能するかは KeyMelier には確認できません。", "rp.empty": "古いキーについてはまだ何もわかっていません。接続して、パスキー・コード・OpenPGP・PIV を一度読み取ってください。", "rp.noRemember": "「内容を記憶」がオフです。保存された内容がないと、KeyMelier はキーを比較できず、進捗も保存できません。", "rp.readNew": "新しいキーはまだ（完全には）読み取られていません。接続して、パスキー（PIN を使用）とその他の項目を開くと、KeyMelier が項目を確認します。", "rp.session": "履歴がオフです。進捗は KeyMelier を終了するまでしか保持されません。", "rp.pk.title": "パスキー", "rp.pk.hint": "パスキーはコピーできません。秘密鍵がキーの外に出ることはありません。サービスにサインインし、新しいキーを追加のパスキーまたはセキュリティキーとして登録し、それでサインインできることを確認してください。その後で古いキーをサービスから削除します。", "rp.oath.hint": "コードのシークレットはキーから読み出せません。サービスで 2 段階認証を再設定する（新しい QR コード）か、元の QR コードを安全に保管している場合はそれを追加してください。", "rp.pgp.hint": "秘密鍵のバックアップ（gpg で作成してキーに移したもの）がある場合に限り、同じ鍵を新しいキーに読み込めます。その場合フィンガープリントが一致します。キー上で生成した鍵は移せません。新しく生成し、公開鍵を配布し、古い鍵を失効させてください。", "rp.piv.hint": "キー上で生成した PIV 鍵は移せません。新しいキーで新しい鍵ペアを生成し、発行元（例：IT 部門）に証明書を再発行してもらってください。同じ名前の証明書は手がかりにすぎず、同じ鍵ではありません。", "rp.otp.hint": "OTP スロットの内容は誰にも読み取れません。保存したシークレットを使って新しいキーに静的パスワードやチャレンジレスポンスを再設定し、サービスやプログラムに登録してください。", "rp.never": "KeyMelier はどちらのキーもリセットせず、何も削除しません。すべてを移行し、どこでも新しいキーでサインインできるようになったら、各サービスから古いキーを削除してください。その後でのみ、ご自身でリセットしてください。", "rp.openNew": "新しいキーを開く", "rp.openNewOffline": "新しいキーを表示（未接続）", "rp.stop": "比較を終了"},
  ko: {"rp.title": "이전 키 교체", "rp.text": "KeyMelier가 이전 키에 대해 알고 있는 내용을 새 키와 비교하고, 서비스별로 옮기는 과정을 안내합니다.", "rp.old": "이전 키", "rp.new": "새 키", "rp.choose": "키 선택…", "rp.check.found": "새 키에서 확인됨", "rp.check.similar": "비슷한 항목 – 확실하지 않음", "rp.check.missing": "새 키에서 찾을 수 없음", "rp.check.unknown": "새 키를 아직 읽지 않음", "rp.confirmed": "직접 확인함", "rp.sum.total": "이전 키의 항목", "rp.sum.found": "새 키에서 기술적으로 확인됨", "rp.sum.confirmed": "직접 완료로 확인함", "rp.legend": "‘확인됨’은 새 키를 마지막으로 읽었을 때 표시된 내용을 바탕으로 KeyMelier가 직접 판단합니다. 체크 표시는 사용자의 확인일 뿐이며, 서비스 로그인이 되는지는 KeyMelier가 확인할 수 없습니다.", "rp.empty": "이전 키에 대해 아직 알려진 것이 없습니다. 연결한 뒤 패스키, 코드, OpenPGP, PIV를 한 번 읽어 주세요.", "rp.noRemember": "‘내용 기억’이 꺼져 있습니다. 저장된 내용이 없으면 KeyMelier가 키를 비교하거나 진행 상황을 저장할 수 없습니다.", "rp.readNew": "새 키를 아직 (완전히) 읽지 않았습니다. 연결한 뒤 패스키(PIN 사용)와 다른 항목을 열면 KeyMelier가 항목을 확인합니다.", "rp.session": "기록이 꺼져 있습니다. 진행 상황은 KeyMelier를 종료할 때까지만 유지됩니다.", "rp.pk.title": "패스키", "rp.pk.hint": "패스키는 복사할 수 없습니다. 개인 키는 절대 키 밖으로 나가지 않습니다. 서비스에 로그인해 새 키를 추가 패스키 또는 보안 키로 등록하고, 새 키로 로그인되는지 확인하세요. 그런 다음에만 서비스에서 이전 키를 제거하세요.", "rp.oath.hint": "코드의 비밀 값은 키에서 읽어 낼 수 없습니다. 서비스에서 2단계 인증을 다시 설정하거나(새 QR 코드), 원래 QR 코드를 안전하게 보관했다면 그것을 추가하세요.", "rp.pgp.hint": "개인 키 백업(gpg에서 만든 뒤 키로 옮긴 것)이 있을 때만 같은 키를 새 키에 넣을 수 있으며, 이때 지문이 일치합니다. 키에서 생성한 키는 옮길 수 없습니다. 새로 생성하고 공개 키를 배포한 뒤 이전 키를 폐기하세요.", "rp.piv.hint": "키에서 생성한 PIV 키는 옮길 수 없습니다. 새 키에서 새 키 쌍을 생성하고 발급처(예: IT 부서)에 인증서 재발급을 요청하세요. 같은 이름의 인증서는 단서일 뿐 같은 키가 아닙니다.", "rp.otp.hint": "OTP 슬롯의 내용은 누구도 읽을 수 없습니다. 저장해 둔 비밀 값으로 새 키에 정적 비밀번호나 챌린지-응답을 다시 설정하고 서비스나 프로그램에 등록하세요.", "rp.never": "KeyMelier는 두 키 모두 초기화하지 않으며 아무것도 삭제하지 않습니다. 모두 옮기고 어디서나 새 키로 로그인할 수 있게 되면 각 서비스에서 이전 키를 제거하세요. 그 후에만 직접 초기화하세요.", "rp.openNew": "새 키 열기", "rp.openNewOffline": "새 키 보기(연결 안 됨)", "rp.stop": "비교 종료"},
  zh: {"rp.title": "替换旧密钥", "rp.text": "将 KeyMelier 对旧密钥所知的内容与新密钥进行比较，并逐个服务引导你完成迁移。", "rp.old": "旧密钥", "rp.new": "新密钥", "rp.choose": "选择密钥…", "rp.check.found": "已在新密钥上找到", "rp.check.similar": "类似条目 – 无法确定", "rp.check.missing": "新密钥上未找到", "rp.check.unknown": "尚未读取新密钥", "rp.confirmed": "你已确认", "rp.sum.total": "旧密钥上的条目", "rp.sum.found": "已在新密钥上经技术确认", "rp.sum.confirmed": "你确认已完成", "rp.legend": "“已找到”由 KeyMelier 根据新密钥上次读取时显示的内容自行判断。勾选仅代表你的确认——KeyMelier 无法检查在服务上登录是否可用。", "rp.empty": "尚不了解旧密钥的任何内容。请连接它，并读取一次通行密钥、验证码、OpenPGP 和 PIV。", "rp.noRemember": "“记住内容”已关闭——没有保存的内容，KeyMelier 无法比较密钥，也无法保存进度。", "rp.readNew": "新密钥尚未（完整）读取。请连接它并打开通行密钥（使用 PIN）及其他部分，KeyMelier 随后会检查这些条目。", "rp.session": "历史记录已关闭：进度只保留到退出 KeyMelier 为止。", "rp.pk.title": "通行密钥", "rp.pk.hint": "通行密钥无法复制——私钥永远不会离开密钥。请登录服务，在那里将新密钥添加为另一个通行密钥或安全密钥，并用它测试登录。之后再从服务中移除旧密钥。", "rp.oath.hint": "验证码的密钥无法从密钥中读取。请在服务上重新设置两步验证（新的二维码），或者如果你妥善保存了原始二维码，就添加它。", "rp.pgp.hint": "只有在拥有私钥备份（在 gpg 中创建后再移到密钥上）时，才能把相同的密钥加载到新密钥上——此时指纹一致。在密钥上生成的密钥无法转移：请生成新的密钥，发布公钥并吊销旧密钥。", "rp.piv.hint": "在密钥上生成的 PIV 密钥无法转移。请在新密钥上生成新的密钥对，并请签发方（例如你的 IT 部门）重新签发证书。同名证书只是线索，并不是同一把密钥。", "rp.otp.hint": "没有人能读取 OTP 槽位的内容。请使用你保存的密钥在新密钥上重新设置静态密码或质询-响应，并在服务或程序中登记。", "rp.never": "KeyMelier 不会重置任何一把密钥，也不会删除任何内容。当一切都已迁移且你在各处都能用新密钥登录后，请在每个服务中移除旧密钥——之后再由你自己重置它。", "rp.openNew": "打开新密钥", "rp.openNewOffline": "显示新密钥（未连接）", "rp.stop": "结束比较"},
};
for (const [code, strings] of Object.entries(RP_STRINGS)) Object.assign(STRINGS[code], strings);

